// Original chiptune: two melodic phrases, arpeggiated harmony and triangle bass.
export class ChipAudio {
 constructor(){this.ctx=null;this.timer=null;this.step=0;this.music=.5;this.sfx=.5;this.master=.5;this.musicTrack=new Audio('assets/snd_music.wav');this.musicTrack.loop=true;this.trackName='music';this.musicTrack.volume=this.music*this.master;this.samples={click:'snd_click',equip:'snd_coin',error:'snd_alert',advance:'snd_voyage',success:'snd_success',launch:'snd_launch'};this.sounds={};for(const [k,v] of Object.entries(this.samples)){this.sounds[k]=new Audio(`assets/${v}.wav`);this.sounds[k].volume=this.sfx;}try{const s=JSON.parse(localStorage.getItem('beeyond-audio'));if(s){this.music=s.music;this.sfx=s.sfx;this.master=s.master??.5;this.musicTrack.volume=this.music*this.master;for(const a of Object.values(this.sounds))a.volume=this.sfx*this.master;}}catch{} }
 setTrack(name){if(!['music','voyage'].includes(name)||this.trackName===name)return;this.trackName=name;this.musicTrack.pause();this.musicTrack=new Audio(`assets/snd_${name}.wav`);this.musicTrack.loop=true;this.musicTrack.volume=this.music*this.master;if(this.ctx?.state==='running'&&this.music>0)this.musicTrack.play().catch(()=>{});}
 async start(){this.ctx??=new AudioContext();await this.ctx.resume();if(this.music>0&&this.musicTrack.paused)this.musicTrack.play().catch(()=>{});if(!this.timer){this.next=this.ctx.currentTime+.06;this.timer=setInterval(()=>this.schedule(),80);}}
 note(midi,time,len,volume,type='square'){if(!this.ctx||volume<=0)return;const o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type=type;o.frequency.value=440*2**((midi-69)/12);g.gain.setValueAtTime(0,time);g.gain.linearRampToValueAtTime(volume,time+.008);g.gain.exponentialRampToValueAtTime(.0001,time+len);o.connect(g);g.connect(this.ctx.destination);o.start(time);o.stop(time+len+.02);}
 schedule(){if(this.ctx.state!=='running')return;const melody=[72,0,76,79,0,76,74,0,72,0,67,0,69,72,0,0,74,0,77,81,0,79,77,0,76,0,74,72,0,67,0,0];while(this.next<this.ctx.currentTime+.2){const i=this.step%32,bass=[48,45,53,55][Math.floor(i/8)];if(melody[i])this.note(melody[i],this.next,.24,this.music*this.master*.085);this.note(bass+[12,19,24,19][i%4],this.next,.13,this.music*this.master*.035,'triangle');if(i%4===0)this.note(bass,this.next,.5,this.music*this.master*.16,'triangle');this.next+=.205;this.step++;}}
 effect(kind='click'){const sound=this.sounds[kind];if(sound&&this.sfx>0){sound.currentTime=0;sound.volume=this.sfx*this.master;sound.play().catch(()=>{});}if(!this.ctx)return;const notes={click:[76],equip:[72,79],error:[48,46],advance:[60,67,72],success:[72,76,79,84]}[kind]||[76];notes.forEach((n,i)=>this.note(n,this.ctx.currentTime+i*.075,.12,this.sfx*this.master*.12));}
 set(k,v){this[k]=Number(v);if(k==='master'){this.musicTrack.volume=this.music*this.master;for(const a of Object.values(this.sounds))a.volume=this.sfx*this.master;}if(k==='music'){this.musicTrack.volume=this.music*this.master;if(this.music===0)this.musicTrack.pause();else if(this.ctx?.state==='running')this.musicTrack.play().catch(()=>{});}if(k==='sfx')for(const a of Object.values(this.sounds))a.volume=this.sfx;try{localStorage.setItem('beeyond-audio',JSON.stringify({music:this.music,sfx:this.sfx,master:this.master}));}catch{}}
 pause(){if(this.ctx)this.ctx.suspend();this.musicTrack.pause();}resume(){if(this.ctx){this.next=this.ctx.currentTime+.06;this.ctx.resume();if(this.music>0)this.musicTrack.play().catch(()=>{});}}
}
